&lt;li&gt;
&lt;p data-path-to-node=&quot;11,1,0&quot;&gt;🛠️ &lt;strong data-path-to-node=&quot;11,1,0&quot; data-index-in-node=&quot;4&quot;&gt;Stack technique moderne :&lt;/strong&gt; GCP, Vertex AI, modèles de fondation récents et ressources dédiées pour tester tes prototypes à l&#39;échelle.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.1;&quot; data-path-to-node=&quot;13&quot;&gt;&lt;strong data-path-to-node=&quot;13&quot; data-index-in-node=&quot;0&quot;&gt;Missions principales&lt;/strong&gt;&lt;/p&gt;
&lt;ul data-path-to-node=&quot;14&quot;&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;14,0,0&quot;&gt;🔍 &lt;strong data-path-to-node=&quot;14,0,0&quot; data-index-in-node=&quot;3&quot;&gt;Audit &amp;amp; Discovery :&lt;/strong&gt; repérer les zones de friction dans nos outils et identifier les cas d&#39;usage où l&#39;IA surpasse les solutions en place.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;14,1,0&quot;&gt;🤖 &lt;strong data-path-to-node=&quot;14,1,0&quot; data-index-in-node=&quot;3&quot;&gt;Prototypage &amp;amp; R&amp;amp;D :&lt;/strong&gt; coder et éprouver des architectures agentiques et des pipelines RAG avancés.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;14,2,0&quot;&gt;📊 &lt;strong data-path-to-node=&quot;14,2,0&quot; data-index-in-node=&quot;3&quot;&gt;Évaluation &amp;amp; LLMOps :&lt;/strong&gt; mesurer la performance de tes modèles selon des critères précis (latence, précision, coût, valeur métier).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;14,3,0&quot;&gt;🔗 &lt;strong data-path-to-node=&quot;14,3,0&quot; data-index-in-node=&quot;3&quot;&gt;Protocoles d&#39;interaction :&lt;/strong&gt; tester l&#39;intégration de standards récents (MCP, échanges Agent-to-Agent) avec notre écosystème Data et SIRH.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;14,4,0&quot;&gt;🎙️ &lt;strong data-path-to-node=&quot;14,4,0&quot; data-index-in-node=&quot;4&quot;&gt;Restitution &amp;amp; impact :&lt;/strong&gt; présenter tes démonstrations aux équipes produit et tech pour orienter les architectures de demain.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.1;&quot; data-path-to-node=&quot;16&quot;&gt;&lt;strong data-path-to-node=&quot;16&quot; data-index-in-node=&quot;0&quot;&gt;Profil recherché&lt;/strong&gt;&lt;/p&gt;
&lt;ul data-path-to-node=&quot;17&quot;&gt;
