&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; style=&quot;text-align: justify;&quot; data-block=&quot;true&quot; data-editor=&quot;fvcfa&quot; data-offset-key=&quot;14mh3-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;14mh3-0-0&quot;&gt;&lt;span data-offset-key=&quot;14mh3-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Knowledge with PostgreSQL or Elasticsearch is a plus.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
